cd /Users/huyaohua/huyh/work/aisuangua && python3 - <<'EOF'
import re
p='.dev/knowledge/方向底稿.md'
t=open(p).read()
lines=t.split('\n')
heads={}
for i,l in enumerate(lines,1):
    m=re.match(r'^#{2,3} (\d+(?:\.\d+)?)', l)
    if m: heads[m.group(1)]=(i,l)
print('标题:', {k:v[0] for k,v in heads.items()})
refs=set()
for i,l in enumerate(lines,1):
    for m in re.finditer(r'§(\d+(?:\.\d+)?)', l):
        refs.add((m.group(1),i))
bad=[(r,i) for r,i in sorted(refs) if r not in heads]
print('引用编号集合:', sorted({r for r,_ in refs}))
print('指向不存在章节:', bad)
# 不带 § 的 "见 X" 引用
for i,l in enumerate(lines,1):
    for m in re.finditer(r'第 (\d+) 节第 (\d+) 条', l):
        sec,item=m.groups()
        print(f'第 {sec} 节第 {item} 条 @{i} -> §{sec} 存在={sec in heads}')
EOF
